cssVarsTemplate:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 23 78.3% 17%;
    --card: 0 0% 100%;
    --card-foreground: 23 78.3% 17%;
    --popover: 0 0% 100%;
    --popover-foreground: 23 78.3% 17%;
    --primary: 24 78.2% 26.6%;
    --primary-foreground: 41 100% 95.9%;
    --secondary: 43 97.5% 88.8%;
    --secondary-foreground: 24 78.2% 26.6%;
    --muted: 43 97.5% 88.8%;
    --muted-foreground: 36 93.3% 50.2%;
    --accent: 43 97.5% 88.8%;
    --accent-foreground: 24 78.2% 26.6%;
    --destructive: 10 85% 58%;
    --destructive-foreground: 41 100% 95.9%;
    --border: 43 98.1% 76.5%;
    --input: 43 98.1% 76.5%;
    --ring: 23 78.3% 17%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
  }

  .dark {
    --background: 23 78.3% 17%;
    --foreground: 41 100% 95.9%;
    --card: 23 78.3% 17%;
    --card-foreground: 41 100% 95.9%;
    --popover: 23 78.3% 17%;
    --popover-foreground: 41 100% 95.9%;
    --primary: 41 100% 95.9%;
    --primary-foreground: 24 78.2% 26.6%;
    --secondary: 26 83.3% 31.4%;
    --secondary-foreground: 41 100% 95.9%;
    --muted: 26 83.3% 31.4%;
    --muted-foreground: 42 98.8% 56.3%;
    --accent: 26 83.3% 31.4%;
    --accent-foreground: 41 100% 95.9%;
    --destructive: 10 63% 29%;
    --destructive-foreground: 41 100% 95.9%;
    --border: 26 83.3% 31.4%;
    --input: 26 83.3% 31.4%;
    --ring: 43 99.2% 64.5%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}
